\begin{lstlisting}
	\xa7\color{blue}@pre: $0\le l \wedge u < |a|$\color{blue}\xa7
	\xa7\color{blue}@post: rv = true $\iff$ $\exists i\colon l\le i \le u \wedge a[i]=e$\xa7
	Bool LinearSearch(int[]a, int l, int u, int e)
	{
		\xa7\color{blue}@L: $l\le i\wedge (\forall j\colon l\le j<i \implies a[j]\ne e)$\xa7
		for(int i := l; i $\le$ u; i := i+1){
			if(a[i]=e) 
			return true;
		}
		return false;
	}
\end{lstlisting}
